        FundamentalTetrahedronAccessors_ = FundamentalTetrahedronAccessors(M);
        Vertices = @FundamentalTetrahedronAccessors_.Vertices;
        Vertices_0 = @FundamentalTetrahedronAccessors_.Vertices_0;
        Vertices_1 = @FundamentalTetrahedronAccessors_.Vertices_1;
