            % f = FaceIndex(i, j, k)
            f = FaceIndex(i, j, k);
            tuple_3 = NeighborVerticesInFace(f, i);
            ret_14 = tuple_3(1);
            ret_15 = tuple_3(2);
        end
        output.V = V;
        output.E = E;
