    function [ret] = e(i, j)
        assert(numel(i) == 1);
        assert(numel(j) == 1);
        assert( ismember(i, V) );
        assert( ismember(j, V) );

        ret = norm(x(i,:)' - x(j,:)', 2);
    end

    function [ret_1, ret_2] = ComputeInternalForces(i, v, p)
        dim_1 = size(v, 1);
        assert(numel(i) == 1);
        assert( isequal(size(v), [dim_1, 3]) );
        assert( isequal(size(p), [dim_1, 3]) );
        assert( ismember(i, V) );

        % f = (∑_(j ∈ VertexOneRing(i)) (-K) (||d|| - e(i, j)) d̄ 
        % where d = p_i - p_j,
        % d̄ = d/||d||)
        sum_0 = zeros(3,1);
        range = VertexOneRing(i);
        for index = 1:length(range)
            j = range(index);
                % d = p_i - p_j
            d = p(i,:)' - p(j,:)';
                % d̄ = d/||d||
            d_bar = d / norm(d, 2);
            sum_0 = sum_0 + (-K) * (norm(d, 2) - e(i, j)) * d_bar;
        end
        f = (sum_0);

        % ṽ = v_i exp(-`Δt` damping) + `Δt` f
        v_tilde = v(i,:)' * exp(-Delta_t * damping) + Delta_t * f;
        tuple = [v_tilde,f + [0.0; -98.0; 0.0]];
        ret_1 = tuple(1);
        ret_2 = tuple(2);
    end

    function [ret_3, ret_4] = ApplyForces(i, v, f, p)
        dim_2 = size(v, 1);
        assert(numel(i) == 1);
        assert( isequal(size(v), [dim_2, 3]) );
        assert( isequal(size(f), [dim_2, 3]) );
        assert( isequal(size(p), [dim_2, 3]) );
        assert( ismember(i, V) );

        % a = f_i / m
        a = f(i,:)' / m;

        % v̄ = v_i + a `Δt`
        v_bar = v(i,:)' + a * Delta_t;

        % ṽ = { (0, -v̄_2, 0) if p_i,2 < bottom
        %       v̄ otherwise
        if p(i,2) < bottom
            v_tilde = [0; -v_bar(2); 0];
        else
            v_tilde = v_bar;
        end

        % p̃ = { (p_i,1, bottom, p_i,3) if p_i,2 < bottom
        %      p_i otherwise
        if p(i,2) < bottom
            p_tilde = [p(i,1); bottom; p(i,3)];
        else
            p_tilde = p(i,:)';
        end

        % x̃ = p̃ + ṽ `Δt`
        x_tilde = p_tilde + v_tilde * Delta_t;
        tuple_1 = [v_tilde,x_tilde];
        ret_3 = tuple_1(1);
        ret_4 = tuple_1(2);
    end

